def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid with 1-indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        grid[x][y] = v

    # DP over steps t = x1 + y1 = x2 + y2
    # Use two layers to save memory
    NEG = -10**18
    prev = [[NEG] * (N + 1) for _ in range(N + 1)]
    # t = 2 (both at (1,1))
    prev[1][1] = grid[1][1]

    for t in range(3, 2 * N + 1):
        cur = [[NEG] * (N + 1) for _ in range(N + 1)]
        for x1 in range(1, N + 1):
            y1 = t - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(1, N + 1):
                y2 = t - x2
                if y2 < 1 or y2 > N:
                    continue
                best = NEG
                # previous positions: (x1-1, x2-1), (x1-1, x2), (x1, x2-1), (x1, x2)
                for dx1 in (0, 1):
                    for dx2 in (0, 1):
                        px1 = x1 - dx1
                        px2 = x2 - dx2
                        if px1 < 1 or px2 < 1:
                            continue
                        val = prev[px1][px2]
                        if val > best:
                            best = val
                if best == NEG:
                    continue
                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                cur[x1][x2] = best + add
        prev = cur

    return prev[N][N] if prev[N][N] != NEG else 0

