def verify_isbn(isbn: str) -> str:
    # Remove hyphens and parse digits
    parts = isbn.split('-')
    if len(parts) != 4:
        # Unexpected format, but still try to process
        digits_str = isbn.replace('-', '')
    else:
        digits_str = ''.join(parts)
    if len(digits_str) != 10:
        # Invalid length, cannot correct
        return isbn
    digits = []
    for i, ch in enumerate(digits_str):
        if ch == 'X':
            if i != 9:
                # 'X' only allowed at last position
                return isbn
            digits.append(10)
        elif ch.isdigit():
            digits.append(int(ch))
        else:
            # Invalid character
            return isbn
    # Compute checksum
    total = sum((i + 1) * digits[i] for i in range(10))
    if total % 11 == 0:
        return "Right"
    # Compute correct checksum digit
    sum9 = sum((i + 1) * digits[i] for i in range(9))
    # d10 ≡ (-sum9 * 10) mod 11
    d10 = (-sum9 * 10) % 11
    corrected_last = 'X' if d10 == 10 else str(d10)
    # Reconstruct corrected ISBN preserving hyphens
    if len(parts) == 4:
        corrected_parts = parts[:3] + [corrected_last]
        return '-'.join(corrected_parts)
    else:
        # If format not as expected, just replace last character
        corrected_digits_str = digits_str[:9] + corrected_last
        return corrected_digits_str

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    horizontal_positions = list(range(1, M))
    vertical_positions = list(range(1, N))
    pair_h = []
    pair_v = []
    for (x1, y1, x2, y2) in chatting_pairs:
        hset = set()
        for r in horizontal_positions:
            if (x1 <= r < x2) or (x2 <= r < x1):
                hset.add(r)
        vset = set()
        for c in vertical_positions:
            if (y1 <= c < y2) or (y2 <= c < y1):
                vset.add(c)
        pair_h.append(hset)
        pair_v.append(vset)
    best_count = -1
    best_rows = []
    best_cols = []
    from itertools import combinations
    for rows in combinations(horizontal_positions, K):
        rows_set = set(rows)
        for cols in combinations(vertical_positions, L):
            cols_set = set(cols)
            count = 0
            for hset, vset in zip(pair_h, pair_v):
                if hset & rows_set or vset & cols_set:
                    count += 1
            if count > best_count:
                best_count = count
                best_rows = rows
                best_cols = cols
    best_rows_sorted = sorted(best_rows)
    best_cols_sorted = sorted(best_cols)
    row_str = ' '.join(map(str, best_rows_sorted))
    col_str = ' '.join(map(str, best_cols_sorted))
    return (row_str, col_str)

